-- 自动生成的模块搭配测试文件
-- 在 andlua 中运行，把输出日志发回

local function run_test(name, encoded)
  io.write("[TEST] " .. name .. " ... ")
  local ok, data = pcall(string.dec, encoded)
  if not ok then
    print("DEC_FAIL: " .. tostring(data))
    return
  end
  local ok2, func = pcall(load, data)
  if not ok2 then
    print("LOAD_FAIL: " .. tostring(func))
    return
  end
  -- 捕获 print 输出
  local old_print = print
  local outputs = {}
  print = function(...)
    local p = {}
    for i = 1, select('#', ...) do p[i] = tostring(select(i, ...)) end
    table.insert(outputs, table.concat(p, "\t"))
  end
  local ok3, err = pcall(func)
  print = old_print
  if not ok3 then
    print("RUN_FAIL: " .. tostring(err))
  else
    print("PASS (" .. #outputs .. " lines)")
  end
end

print("=== 模块搭配测试开始 ===")
print("时间: " .. os.date())

run_test("none", "")

run_test("bool", "")

run_test("num", "")

run_test("str_split", "")

run_test("bool+num", "")

run_test("bool+str", "")

run_test("num+str", "")

run_test("bool+num+str", "")

run_test("base6", "")

run_test("base6+poison", "")

run_test("base+junk", "")

run_test("base+junk+cf", "")

run_test("full_noantitd", "")

run_test("full_all", "")

run_test("str_only+antitd", "")

run_test("junk_only", "")

run_test("cf_only", "")

run_test("str+cf", "")

run_test("num+str+junk", "")

print("=== 测试结束 ===")